package com.personalassistant.companion;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.media.ExifInterface;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.Consumer;

/**
 * Private progress photos: originals in the owner's cloud, comparison shots kept apart from flexed ones by state, and the coach only
 * sees photos the owner approves for that one question.
 */
final class WorkoutPhotos {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;final WorkoutViews.Sheet sheet;final HashSet<String> selected=new HashSet<>();LinearLayout grid;Button ask;String state="relaxed";
    WorkoutPhotos(WorkoutScreen s,WorkoutViews.Sheet sheet){screen=s;a=s.a;ui=s.ui;this.sheet=sheet;}

    static byte[] read(Context c,Uri uri,int limit)throws IOException{try(InputStream in=c.getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>limit)throw new IOException("Too large");}return out.toByteArray();}}

    void fill(){LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Photos",15,20,700,0,ui.text));LinearLayout tabs=ui.row();for(String[] t:new String[][]{{"relaxed","Relaxed"},{"flexed","Flexed"},{"pumped","Pumped"}}){TextView v=ui.type(t[1],13,18,600,0,state.equals(t[0])?ui.accent:ui.muted);v.setPadding(ui.dp(4),ui.dp(10),ui.dp(16),ui.dp(10));v.setOnClickListener(x->{state=t[0];selected.clear();sheetRefresh();});tabs.addView(v);}c.addView(tabs);grid=ui.column();c.addView(grid);ask=ui.quietButton("Choose photos to ask about",this::ask);c.addView(ask,MainParts.params(ui,-1,-2,0,8,0,6));c.addView(ui.quietButton("Add photo",()->add()),WorkoutViews.gap(ui,6));c.addView(ui.type("Each look by your coach needs your approval. Any estimate is a rough range.",12,16,400,0,ui.muted));sheet.body.addView(c,WorkoutViews.gap(ui,10));JSONArray est=estimates();for(int i=est.length()-1;i>=Math.max(0,est.length()-3);i--){JSONObject e=est.optJSONObject(i);sheet.body.addView(ui.type("Rough visual estimate "+WorkoutViews.kg(e.optDouble("low_percent"))+"–"+WorkoutViews.kg(e.optDouble("high_percent"))+"% · "+e.optString("assessed_at").substring(0,10)+". Not a measurement.",12.5f,17,400,0,ui.muted),WorkoutViews.gap(ui,4));}paint();}
    private void sheetRefresh(){View card=(View)grid.getParent();int at=sheet.body.indexOfChild(card);sheet.body.removeViewAt(at);while(sheet.body.getChildCount()>at)sheet.body.removeViewAt(at);fill();}
    private JSONArray estimates(){JSONArray out=new JSONArray();List<JSONObject> r=WorkoutStore.rows(a,"composition");Collections.sort(r,(x,y)->x.optJSONObject("data").optString("assessed_at").compareTo(y.optJSONObject("data").optString("assessed_at")));for(JSONObject x:r)out.put(x.optJSONObject("data"));return out;}
    private static final DateTimeFormatter SHORT=DateTimeFormatter.ofPattern("d MMM yy"),LONG=DateTimeFormatter.ofPattern("EEEE d MMMM yyyy");
    private LocalDate day(JSONObject d){String at=d.optString("captured_at");try{return OffsetDateTime.parse(at).atZoneSameInstant(ZoneId.systemDefault()).toLocalDate();}catch(Exception e){return LocalDate.parse(at.substring(0,10));}}
    /** The sprint the photo was taken in: recorded at upload, or worked out from its date for older photos. */
    private String sprint(JSONObject d){String id=d.optString("sprint_id");JSONObject own=id.isEmpty()?null:WorkoutStore.data(a,"sprint",id);if(own!=null)return own.optString("name");String on=day(d).toString();for(JSONObject r:WorkoutStore.rows(a,"sprint")){JSONObject x=r.optJSONObject("data");if(on.compareTo(x.optString("start"))>=0&&on.compareTo(x.optString("end"))<=0)return x.optString("name");}return "";}
    private String currentSprint(){JSONObject s=WorkoutStore.sprint(a);if(s==null)return null;JSONObject d=s.optJSONObject("data");String today=LocalDate.now().toString();return today.compareTo(d.optString("start"))>=0&&today.compareTo(d.optString("end"))<=0?s.optString("id"):null;}
    /** Newest first, under the sprint each photo belongs to. */
    private void paint(){grid.removeAllViews();List<JSONObject> photos=WorkoutStore.rows(a,"photo");Collections.sort(photos,(x,y)->y.optJSONObject("data").optString("captured_at").compareTo(x.optJSONObject("data").optString("captured_at")));LinkedHashMap<String,List<JSONObject>> groups=new LinkedHashMap<>();for(JSONObject p:photos){JSONObject d=p.optJSONObject("data");if(!state.equals(d.optString("state")))continue;String name=sprint(d);if(!groups.containsKey(name))groups.put(name,new ArrayList<>());groups.get(name).add(p);}if(groups.isEmpty())grid.addView(ui.type("None yet. Morning light, unpumped, same spot each time works best.",13,18,400,0,ui.muted));for(Map.Entry<String,List<JSONObject>> g:groups.entrySet()){grid.addView(ui.type(g.getKey().isEmpty()?"Outside a sprint":g.getKey(),13,18,700,0,g.getKey().isEmpty()?ui.muted:ui.accent),MainParts.params(ui,-1,-2,0,6,0,6));LinearLayout row=null;int n=0;for(JSONObject p:g.getValue()){if(n++%3==0){row=ui.row();grid.addView(row,MainParts.params(ui,-1,ui.dp(138),0,0,0,4));}row.addView(tile(p),new LinearLayout.LayoutParams(0,-1,1));}if(row!=null)for(;n%3!=0;n++)row.addView(new View(a),new LinearLayout.LayoutParams(0,-1,1));}}
    private void asked(){ask.setText(selected.isEmpty()?"Choose photos to ask about":"Ask coach about "+selected.size()+(selected.size()==1?" photo":" photos"));}
    /** A tap selects, with a ring and a tick over the picture; a hold opens it. */
    private View tile(JSONObject p){JSONObject d=p.optJSONObject("data");String id=p.optString("id");FrameLayout f=new FrameLayout(a);f.setPadding(ui.dp(2),ui.dp(2),ui.dp(2),ui.dp(2));ImageView img=new ImageView(a);img.setScaleType(ImageView.ScaleType.CENTER_CROP);img.setBackground(ui.outline(ui.surfaceAlt,10,0,0));img.setClipToOutline(true);img.setContentDescription(d.optString("pose")+" photo, "+day(d).format(LONG));f.addView(img,new FrameLayout.LayoutParams(-1,-1));TextView date=ui.type(day(d).format(SHORT),11,15,700,0,0xFFFFFFFF);date.setPadding(ui.dp(6),ui.dp(2),ui.dp(6),ui.dp(2));date.setBackground(ui.outline(0xB3000000,8,0,0));FrameLayout.LayoutParams at=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.START);at.setMargins(ui.dp(4),0,0,ui.dp(4));f.addView(date,at);FrameLayout mark=new FrameLayout(a);mark.setTag("photo_selected");mark.setBackground(ui.outline(AppUi.alpha(ui.accent,.24f),10,ui.accent,3));FrameLayout tick=new FrameLayout(a);tick.setBackground(ui.outline(ui.accent,13,0xFFFFFFFF,2));tick.addView(MainParts.icon(ui,"check",0xFFFFFFFF),new FrameLayout.LayoutParams(ui.dp(16),ui.dp(16),Gravity.CENTER));FrameLayout.LayoutParams corner=new FrameLayout.LayoutParams(ui.dp(26),ui.dp(26),Gravity.TOP|Gravity.END);corner.setMargins(0,ui.dp(5),ui.dp(5),0);mark.addView(tick,corner);mark.setVisibility(selected.contains(id)?View.VISIBLE:View.GONE);f.addView(mark,new FrameLayout.LayoutParams(-1,-1));load(d.optString("blob_id"),img,4);f.setOnClickListener(v->{if(selected.contains(id))selected.remove(id);else if(selected.size()<6)selected.add(id);else{Toast.makeText(a,"Six photos at most",Toast.LENGTH_SHORT).show();return;}v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);mark.setVisibility(selected.contains(id)?View.VISIBLE:View.GONE);asked();});f.setOnLongClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);open(p);return true;});return f;}
    /** The photo nearly full screen. It stays until a tap, a hold or back closes it. */
    private void open(JSONObject p){JSONObject d=p.optJSONObject("data");String id=p.optString("id");Dialog view=ui.sheet();FrameLayout root=new FrameLayout(a);root.setBackgroundColor(0xF5000000);root.setFitsSystemWindows(true);root.setTag("photo_viewer");ImageView img=new ImageView(a);img.setScaleType(ImageView.ScaleType.FIT_CENTER);img.setContentDescription(d.optString("pose")+" photo, "+day(d).format(LONG)+". Tap or hold to close");FrameLayout.LayoutParams fit=new FrameLayout.LayoutParams(-1,-1);fit.setMargins(ui.dp(8),ui.dp(60),ui.dp(8),ui.dp(84));root.addView(img,fit);img.setOnClickListener(v->view.dismiss());img.setOnLongClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);view.dismiss();return true;});LinearLayout top=ui.row();top.setPadding(ui.dp(8),ui.dp(8),ui.dp(8),0);ImageButton close=ui.iconButton("back","Close photo",0xFFFFFFFF,view::dismiss);close.setBackground(ui.outline(0x2EFFFFFF,24,0,0));top.addView(close,new LinearLayout.LayoutParams(ui.dp(46),ui.dp(46)));top.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));ImageButton bin=ui.iconButton("trash","Delete photo",ui.hue(AppUi.RED),()->new AlertDialog.Builder(a).setTitle("Delete this photo?").setMessage("It's removed from your cloud storage too.").setPositiveButton("Delete",(x,i)->{WorkoutStore.delete(a,"photo",id);selected.remove(id);new File(a.getCacheDir(),"workout-photo-"+d.optString("blob_id")).delete();view.dismiss();asked();paint();screen.refresh();}).setNegativeButton("Cancel",null).show());bin.setBackground(ui.outline(0x2EFFFFFF,24,0,0));top.addView(bin,new LinearLayout.LayoutParams(ui.dp(46),ui.dp(46)));root.addView(top,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));LinearLayout words=ui.column();words.setPadding(ui.dp(18),0,ui.dp(18),ui.dp(16));words.addView(ui.type(day(d).format(LONG),16,22,700,0,0xFFFFFFFF));String sprint=sprint(d),pose=d.optString("pose"),kind=d.optString("state");words.addView(ui.type((sprint.isEmpty()?"":sprint+" · ")+pose.substring(0,1).toUpperCase(Locale.ROOT)+pose.substring(1)+" · "+kind.substring(0,1).toUpperCase(Locale.ROOT)+kind.substring(1),13,18,500,0,0xFFD9D2E8));root.addView(words,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));view.setContentView(root);load(d.optString("blob_id"),img,0);view.show();Window w=view.getWindow();if(w!=null)w.setLayout(-1,-1);}
    /** Downsampled for the grid; size 0 keeps up to 2048 px for the large view. Phone photos are turned upright. */
    private static Bitmap decode(byte[] b,int sample){BitmapFactory.Options o=new BitmapFactory.Options();if(sample==0){o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(b,0,b.length,o);sample=Math.max(1,Math.max(o.outWidth,o.outHeight)/2048);o=new BitmapFactory.Options();}o.inSampleSize=sample;Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length,o);int turn=0;try{int e=new ExifInterface(new ByteArrayInputStream(b)).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);turn=e==ExifInterface.ORIENTATION_ROTATE_90?90:e==ExifInterface.ORIENTATION_ROTATE_180?180:e==ExifInterface.ORIENTATION_ROTATE_270?270:0;}catch(IOException ignored){}if(turn==0||bmp==null)return bmp;Matrix m=new Matrix();m.postRotate(turn);return Bitmap.createBitmap(bmp,0,0,bmp.getWidth(),bmp.getHeight(),m,true);}
    private void load(String blob,ImageView into,int sample){File cached=new File(a.getCacheDir(),"workout-photo-"+blob);new Thread(()->{try{byte[] b;if(cached.isFile())b=java.nio.file.Files.readAllBytes(cached.toPath());else{b=Cloud.raw(a,"GET","workout/photos/"+blob,null,null);java.nio.file.Files.write(cached.toPath(),b);}Bitmap bmp=decode(b,sample);a.runOnUiThread(()->into.setImageBitmap(bmp));}catch(Exception ignored){}}).start();}
    private void add(){WorkoutPicker.pick(a,"image/*",uri->new AlertDialog.Builder(a).setTitle("Which pose?").setItems(new String[]{"Front","Side","Back"},(x,i)->upload(uri,new String[]{"front","side","back"}[i])).show());}
    private void upload(Uri uri,String pose){Toast.makeText(a,"Saving to your private storage…",Toast.LENGTH_SHORT).show();new Thread(()->{String problem=null;try{byte[] b=read(a,uri,8*1024*1024);String type=a.getContentResolver().getType(uri);if(type==null||!type.matches("image/(jpeg|png|webp)"))throw new IllegalArgumentException("Use a JPEG, PNG or WebP photo.");StringBuilder hex=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))hex.append(String.format(Locale.ROOT,"%02x",x));Cloud.raw(a,"PUT","workout/photos/"+hex,b,type);JSONObject photo=new JSONObject().put("captured_at",OffsetDateTime.now().withNano(0).toString()).put("blob_id",hex.toString()).put("pose",pose).put("state",state);String sprint=currentSprint();if(sprint!=null)photo.put("sprint_id",sprint);WorkoutStore.put(a,"photo",WorkoutStore.id(),photo);WorkoutStore.sync(a);}catch(IllegalArgumentException e){problem=e.getMessage();}catch(IOException e){problem="Photos must be under 8 MB, and you need a connection to save one.";}catch(Exception e){problem="Couldn't save the photo.";}String m=problem;a.runOnUiThread(()->{if(m!=null)Toast.makeText(a,m,Toast.LENGTH_LONG).show();paint();});}).start();}
    private void ask(){if(selected.isEmpty()){Toast.makeText(a,"Tap photos to select them, hold to open one",Toast.LENGTH_SHORT).show();return;}int n=selected.size();new AlertDialog.Builder(a).setTitle("Send "+n+(n==1?" photo":" photos")+" to your coach?").setMessage("Only "+(n==1?"this photo":"these photos")+" will be analysed, for this question only.").setPositiveButton("Approve",(x,i)->{JSONArray ids=new JSONArray();for(String id:selected)ids.put(id);selected.clear();screen.coach.open(new JSONObject(),null,"Compare these photos and give a rough range only.",ids);}).setNegativeButton("Cancel",null).show();}
}
